+</style>
+</head>
+<body>
+<div id="app">
+  <canvas id="simCanvas"></canvas>
+
+  <div class="top-hud">
+    <div class="brand-card">
+      <div class="brand-dot"></div>
+      <h1>Gemini 4 Argon</h1>
+      <span class="brand-sub">2D Crash Physics Sandbox</span>
+    </div>
+
+    <div class="telemetry-bar">
+      <div class="stat-item">
+        <span class="stat-label">State</span>
+        <span class="stat-value status-pill" id="telState">READY</span>
+      </div>
+      <div class="stat-item">
+        <span class="stat-label">Car Speed</span>
+        <span class="stat-value" id="telSpeed">22.0 m/s</span>
+      </div>
+      <div class="stat-item">
+        <span class="stat-label">Elapsed Time</span>
+        <span class="stat-value" id="telTime">0.00 s</span>
+      </div>
+      <div class="stat-item">
+        <span class="stat-label">Moving Bricks</span>
+        <span class="stat-value" id="telMoving">0 / 192</span>
+      </div>
+      <div class="stat-item">
+        <span class="stat-label">Wall Mass</span>
+        <span class="stat-value" id="telWallMass">480.0 kg</span>
+      </div>
+      <div class="stat-item">
+        <span class="stat-label">Peak Impact</span>
+        <span class="stat-value" id="telPeakForce">0 kN</span>
+      </div>
+    </div>
+
+    <div class="action-bar">
+      <button class="btn-test" id="btnTest" title="Launch Crash Experiment (Space / Enter)">
+        &#9654; Test
+      </button>
+      <button class="btn-secondary" id="btnReset" title="Reset Scene (R)">
+        &#8634; Reset
+      </button>
+      <button class="btn-secondary" id="btnToggleSettings" title="Toggle Settings Panel">
+        &#9881; Settings
+      </button>
+    </div>
+  </div>
+
+  <aside class="settings-panel" id="settingsPanel">
+    <div class="panel-header">
+      <span class="panel-title">Experiment Parameters</span>
+      <button class="btn-defaults" id="btnDefaults">Restore Defaults</button>
+    </div>
+
+    <div class="control-group">
+      <div class="control-header">
+        <label class="control-label" for="inpSpeed">Car Speed</label>
+        <span class="control-val" id="valSpeed">22 m/s (79 km/h)</span>
