+      <input type="range" id="inpCols" min="4" max="24" step="1" value="12" />
+      <div class="range-limits"><span>4 cols</span><span>12 default</span><span>24 cols</span></div>
+    </div>
+
+    <div class="control-group">
+      <div class="control-header">
+        <label class="control-label" for="inpRows">Wall Rows (Height)</label>
+        <span class="control-val" id="valRows">8 bricks (1.92 m)</span>
+      </div>
+      <input type="range" id="inpRows" min="3" max="16" step="1" value="8" />
+      <div class="range-limits"><span>3 rows</span><span>8 default</span><span>16 rows</span></div>
+    </div>
+
+    <div class="control-group">
+      <div class="control-header">
+        <label class="control-label" for="inpLayers">Wall Depth Layers</label>
+        <span class="control-val" id="valLayers">2 layers</span>
+      </div>
+      <input type="range" id="inpLayers" min="1" max="5" step="1" value="2" />
+      <div class="range-limits"><span>1 layer</span><span>2 default</span><span>5 layers</span></div>
+    </div>
+
+    <div class="control-group">
+      <div class="control-header">
+        <label class="control-label" for="inpBrickMass">Brick Mass</label>
+        <span class="control-val" id="valBrickMass">2.5 kg</span>
+      </div>
+      <input type="range" id="inpBrickMass" min="0.5" max="12" step="0.1" value="2.5" />
+      <div class="range-limits"><span>0.5 kg</span><span>2.5 kg default</span><span>12.0 kg</span></div>
+    </div>
+
+    <div class="fixed-specs">
+      <div class="fixed-specs-title">Baseline Physical Constants</div>
+      <div class="specs-grid">
+        <div class="spec-row"><span>Car Mass</span><span>1,250 kg</span></div>
+        <div class="spec-row"><span>Car Size</span><span>4.2×1.45 m</span></div>
+        <div class="spec-row"><span>Brick Size</span><span>0.50×0.24 m</span></div>
+        <div class="spec-row"><span>Gravity</span><span>9.81 m/s²</span></div>
+        <div class="spec-row"><span>Brick μ</span><span>0.72</span></div>
+        <div class="spec-row"><span>Restitution</span><span>0.18</span></div>
+        <div class="spec-row"><span>Ground μ</span><span>0.85</span></div>
+        <div class="spec-row"><span>Sim Scale</span><span>80 px/m</span></div>
+      </div>
+    </div>
+  </aside>
+
+  <div class="bottom-hint">
+    Drag canvas to pan &bull; Scroll to zoom &bull; Double-click to reset camera &bull; Space to Run Test
+  </div>
+</div>
+
+<script>
+(() => {
+  "use strict";
+
+  // ============================================================================
+  // MANDATORY BASELINE EXPERIMENT CONSTANTS & DEFAULTS
+  // ============================================================================
+  const DEFAULTS = Object.freeze({
+    carSpeed: 22,          // m/s
+    wallColumns: 12,       // bricks wide
+    wallRows: 8,           // bricks tall
+    wallDepthLayers: 2,    // layers thick
+    brickMass: 2.5,        // kg per brick
+    brickWidth: 0.50,      // m
+    brickHeight: 0.24,     // m
+    gravity: 9.81,         // m/s^2
+    brickFriction: 0.72,
+    brickRestitution: 0.18,
+    carMass: 1250,         // kg
+    carWidth: 4.2,         // m
+    carHeight: 1.45,       // m
+    groundFriction: 0.85,
+    scale: 80              // pixels per meter
+  });
+
+  // Active configurable state
+  const config = {
+    carSpeed: DEFAULTS.carSpeed,
+    wallColumns: DEFAULTS.wallColumns,
+    wallRows: DEFAULTS.wallRows,
+    wallDepthLayers: DEFAULTS.wallDepthLayers,
+    brickMass: DEFAULTS.brickMass
+  };
+
+  // ============================================================================
+  // DETERMINISTIC SEEDED PRNG (Strictly for visual particles, never physics)
+  // ============================================================================
+  function createSeededRandom(seed) {
+    let t = seed >>> 0;
+    return function() {
+      t += 0x6D2B79F5;
+      let r = Math.imul(t ^ (t >>> 15), 1 | t);
+      r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
+      return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
+    };
+  }
+  let vfxRng = createSeededRandom(1337);
+
+  // ============================================================================
+  // DOM ELEMENTS
+  // ============================================================================
+  const canvas = document.getElementById("simCanvas");
+  const ctx = canvas.getContext("2d");
+
+  const telState = document.getElementById("telState");
+  const telSpeed = document.getElementById("telSpeed");
+  const telTime = document.getElementById("telTime");
+  const telMoving = document.getElementById("telMoving");
+  const telWallMass = document.getElementById("telWallMass");
+  const telPeakForce = document.getElementById("telPeakForce");
+
+  const btnTest = document.getElementById("btnTest");
+  const btnReset = document.getElementById("btnReset");
+  const btnToggleSettings = document.getElementById("btnToggleSettings");
+  const btnDefaults = document.getElementById("btnDefaults");
+  const settingsPanel = document.getElementById("settingsPanel");
+
+  const inpSpeed = document.getElementById("inpSpeed");
+  const inpCols = document.getElementById("inpCols");
+  const inpRows = document.getElementById("inpRows");
+  const inpLayers = document.getElementById("inpLayers");
+  const inpBrickMass = document.getElementById("inpBrickMass");
+
+  const valSpeed = document.getElementById("valSpeed");
+  const valCols = document.getElementById("valCols");
+  const valRows = document.getElementById("valRows");
+  const valLayers = document.getElementById("valLayers");
+  const valBrickMass = document.getElementById("valBrickMass");
+
+  // ============================================================================
+  // 2D RIGID BODY & COLLISION ENGINE (OBB + SAT + SEQUENTIAL IMPULSES)
+  // ============================================================================
+  // Coordinate system:
+  // World X: meters rightwards (track starts at x = 0, wall starts at x = WALL_START_X)
+  // World Y: meters upwards from ground plane (ground is at y = 0, y > 0 is up)
+  const CAR_START_X = 2.6;     // Car center X at start (left side of track)
+  const WALL_START_X = 9.2;    // Front face of the brick wall (meters)
+  const FIXED_DT = 1 / 240;    // 240 Hz fixed physics timestep
+  const VEL_ITERATIONS = 10;
+  const POS_ITERATIONS = 4;
+
+  class RigidBrick {
+    constructor(id, col, row, layer, x, y, w, h, mass, colorVariant) {
+      this.id = id;
+      this.col = col;
+      this.row = row;
+      this.layer = layer;
+
+      this.x = x;
+      this.y = y;
+      this.vx = 0;
+      this.vy = 0;
+      this.angle = 0;
+      this.omega = 0;
+
+      this.w = w;
+      this.h = h;
+      this.hw = w * 0.5;
+      this.hh = h * 0.5;
+      this.radius = Math.hypot(this.hw, this.hh);
+
+      this.mass = mass;
+      this.invMass = 1 / mass;
+      this.inertia = (mass * (w * w + h * h)) / 12;
+      this.invInertia = 1 / this.inertia;
+
+      this.friction = DEFAULTS.brickFriction;
+      this.restitution = DEFAULTS.brickRestitution;
+
+      // Structural mortar cohesion state (breaks when stressed by impact)
+      this.intact = true;
+      this.damage = 0;
+      this.colorVariant = colorVariant;
+
+      // Cached world-space axes and vertices
+      this.cos = 1;
+      this.sin = 0;
+      this.verts = [
+        { x: 0, y: 0 },
+        { x: 0, y: 0 },
+        { x: 0, y: 0 },
+        { x: 0, y: 0 }
+      ];
+      this.updateTransform();
+    }
+
+    updateTransform() {
+      const c = Math.cos(this.angle);
+      const s = Math.sin(this.angle);
+      this.cos = c;
+      this.sin = s;
+      const wx = c * this.hw;
+      const wy = s * this.hw;
+      const hx = -s * this.hh;
+      const hy = c * this.hh;
+
+      // Counter-clockwise vertices: bottom-left, bottom-right, top-right, top-left
+      this.verts[0].x = this.x - wx - hx;
+      this.verts[0].y = this.y - wy - hy;
+      this.verts[1].x = this.x + wx - hx;
+      this.verts[1].y = this.y + wy - hy;
+      this.verts[2].x = this.x + wx + hx;
+      this.verts[2].y = this.y + wy + hy;
+      this.verts[3].x = this.x - wx + hx;
+      this.verts[3].y = this.y - wy + hy;
+    }
+  }
+
+  class CarBody {
+    constructor(x, speed) {
+      this.w = DEFAULTS.carWidth;
+      this.h = DEFAULTS.carHeight;
+      this.hw = this.w * 0.5;
+      this.hh = this.h * 0.5;
+
+      // Ground clearance for chassis bottom is 0.20 m
+      this.clearance = 0.20;
+      this.baseY = this.clearance + this.hh;
+
+      this.x = x;
+      this.y = this.baseY;
+      this.vx = speed;
+      this.vy = 0;
+      this.angle = 0; // Pitch angle (rad)
+      this.omega = 0; // Pitch angular velocity
+
+      this.mass = DEFAULTS.carMass;
+      this.invMass = 1 / this.mass;
+      this.inertia = (this.mass * (this.w * this.w + this.h * this.h)) / 10;
+      this.invInertia = 1 / this.inertia;
+
+      this.friction = 0.45;
+      this.restitution = 0.12;
+
+      // Impact dynamics
+      this.hasImpacted = false;
+      this.crumple = 0; // Front bumper compression (0 .. 0.36 m)
+      this.wheelAngle = 0;
+      this.hoodAngle = 0;
+      this.hoodOmega = 0;
+
+      // Multi-box / sloped front hull represented as 2 convex OBB colliders attached to the car:
+      // 1) Lower chassis + bumper block
+      // 2) Upper cabin + sloped hood/windshield block
+      this.colliders = [];
+      this.updateTransform();
+    }
+
+    updateTransform() {
+      const effectiveW = this.w - this.crumple;
+      const c = Math.cos(this.angle);
+      const s = Math.sin(this.angle);
+      this.cos = c;
+      this.sin = s;
+
+      // Local-to-world helper
+      const toWorld = (lx, ly) => ({
+        x: this.x + lx * c - ly * s,
+        y: this.y + lx * s + ly * c
+      });
