+      // Lower body box (bumper to rear, height 0.68m)
+      const lowHW = effectiveW * 0.5;
+      const lowHH = 0.34;
+      const lowCenter = toWorld(-this.crumple * 0.5, -this.hh + lowHH);
+
+      // Upper cabin + hood box
+      const upHW = effectiveW * 0.34;
+      const upHH = 0.36;
+      const upCenter = toWorld(-this.w * 0.08, -this.hh + 0.68 + upHH * 0.85);
