+      // Front sloped hood ramp collider (angled so high bricks deflect up onto hood/windshield)
+      const rampAngle = this.angle - 0.34;
+      const rc = Math.cos(rampAngle);
+      const rs = Math.sin(rampAngle);
+      const rampHW = 0.62;
+      const rampHH = 0.22;
+      const rampCenter = toWorld(effectiveW * 0.26 - this.crumple * 0.5, 0.06);
