+        this.makeOBB(lowCenter.x, lowCenter.y, lowHW, lowHH, c, s),
+        this.makeOBB(upCenter.x, upCenter.y, upHW, upHH, c, s),
+        this.makeOBB(rampCenter.x, rampCenter.y, rampHW, rampHH, rc, rs)
