+    }
+
+    makeOBB(cx, cy, hw, hh, c, s) {
+      const wx = c * hw;
+      const wy = s * hw;
+      const hx = -s * hh;
+      const hy = c * hh;
+      return {
+        x: cx,
+        y: cy,
+        hw,
+        hh,
+        cos: c,
+        sin: s,
+        radius: Math.hypot(hw, hh),
+        verts: [
+          { x: cx - wx - hx, y: cy - wy - hy },
+          { x: cx + wx - hx, y: cy + wy - hy },
+          { x: cx + wx + hx, y: cy + wy + hy },
+          { x: cx - wx + hx, y: cy - wy + hy }
