+  // ============================================================================
+  // SAT + SUTHERLAND-HODGMAN OBB MANIFOLD GENERATOR
+  // ============================================================================
+  function projectVerts(verts, ax, ay) {
+    let min = Infinity;
+    let max = -Infinity;
+    for (let i = 0; i < 4; i++) {
+      const p = verts[i].x * ax + verts[i].y * ay;
+      if (p < min) min = p;
+      if (p > max) max = p;
+    }
+    return { min, max };
+  }
+
+  function clipSegmentToLine(vIn, normalX, normalY, offset) {
+    const vOut = [];
+    const d0 = vIn[0].x * normalX + vIn[0].y * normalY - offset;
+    const d1 = vIn[1].x * normalX + vIn[1].y * normalY - offset;
+
+    if (d0 <= 0) vOut.push(vIn[0]);
+    if (d1 <= 0) vOut.push(vIn[1]);
+
+    if (d0 * d1 < 0) {
+      const t = d0 / (d0 - d1);
+      vOut.push({
+        x: vIn[0].x + t * (vIn[1].x - vIn[0].x),
+        y: vIn[0].y + t * (vIn[1].y - vIn[0].y)
+      });
+    }
+    return vOut;
+  }
+
+  function findSupportEdge(verts, nx, ny) {
+    let bestDot = -Infinity;
+    let bestIndex = 0;
+    for (let i = 0; i < 4; i++) {
+      const d = verts[i].x * nx + verts[i].y * ny;
+      if (d > bestDot) {
+        bestDot = d;
+        bestIndex = i;
+      }
+    }
+    const v1 = verts[bestIndex];
+    const v0 = verts[(bestIndex + 3) & 3];
+    const v2 = verts[(bestIndex + 1) & 3];
+
+    // Edge vectors
+    const eprevX = v1.x - v0.x;
+    const eprevY = v1.y - v0.y;
+    const lprev = Math.hypot(eprevX, eprevY) || 1;
+
+    const enextX = v1.x - v2.x;
+    const enextY = v1.y - v2.y;
+    const lnext = Math.hypot(enextX, enextY) || 1;
+
+    if (Math.abs((eprevX * nx + eprevY * ny) / lprev) <= Math.abs((enextX * nx + enextY * ny) / lnext)) {
+      return [v0, v1];
+    } else {
+      return [v1, v2];
+    }
+  }
+
+  function collideOBBs(boxA, boxB) {
+    const dx = boxB.x - boxA.x;
+    const dy = boxB.y - boxA.y;
+    const maxDist = boxA.radius + boxB.radius;
+    if (dx * dx + dy * dy > maxDist * maxDist) return null;
+
+    const axes = [
+      { x: boxA.cos, y: boxA.sin },
+      { x: -boxA.sin, y: boxA.cos },
+      { x: boxB.cos, y: boxB.sin },
+      { x: -boxB.sin, y: boxB.cos }
+    ];
+
+    let minOverlap = Infinity;
+    let bestAxisX = 0;
+    let bestAxisY = 0;
+    let bestIndex = 0;
+
+    for (let i = 0; i < 4; i++) {
+      let ax = axes[i].x;
+      let ay = axes[i].y;
+      const pA = projectVerts(boxA.verts, ax, ay);
+      const pB = projectVerts(boxB.verts, ax, ay);
+      const overlap = Math.min(pA.max, pB.max) - Math.max(pA.min, pB.min);
+      if (overlap <= 0) return null;
+
+      if (overlap < minOverlap) {
+        minOverlap = overlap;
+        if (dx * ax + dy * ay < 0) {
+          ax = -ax;
+          ay = -ay;
+        }
+        bestAxisX = ax;
+        bestAxisY = ay;
+        bestIndex = i;
+      }
+    }
+
+    // Reference vs Incident box
+    let refBox = bestIndex < 2 ? boxA : boxB;
+    let incBox = bestIndex < 2 ? boxB : boxA;
+    let refNormalX = bestIndex < 2 ? bestAxisX : -bestAxisX;
+    let refNormalY = bestIndex < 2 ? bestAxisY : -bestAxisY;
+
+    const refEdge = findSupportEdge(refBox.verts, refNormalX, refNormalY);
+    let incEdge = findSupportEdge(incBox.verts, -refNormalX, -refNormalY);
+
+    let sideX = refEdge[1].x - refEdge[0].x;
+    let sideY = refEdge[1].y - refEdge[0].y;
+    const sideLen = Math.hypot(sideX, sideY) || 1;
+    sideX /= sideLen;
+    sideY /= sideLen;
+
+    const negOffset = -(sideX * refEdge[0].x + sideY * refEdge[0].y);
+    const posOffset = sideX * refEdge[1].x + sideY * refEdge[1].y;
+
+    let clipped = clipSegmentToLine(incEdge, -sideX, -sideY, negOffset);
+    if (clipped.length < 2) return null;
+    clipped = clipSegmentToLine(clipped, sideX, sideY, posOffset);
+    if (clipped.length < 2) return null;
+
+    const refOffset = refNormalX * refEdge[0].x + refNormalY * refEdge[0].y;
+    const contacts = [];
+    for (let i = 0; i < clipped.length; i++) {
+      const depth = refOffset - (refNormalX * clipped[i].x + refNormalY * clipped[i].y);
+      if (depth >= -0.002) {
+        contacts.push({
+          x: clipped[i].x,
+          y: clipped[i].y,
+          depth: Math.max(0, depth)
+        });
+      }
+    }
+
+    if (contacts.length === 0) {
+      contacts.push({
+        x: (boxA.x + boxB.x) * 0.5,
+        y: (boxA.y + boxB.y) * 0.5,
+        depth: minOverlap
+      });
+    }
+
+    return {
+      nx: bestAxisX,
+      ny: bestAxisY,
+      contacts
+    };
+  }
