+  // ============================================================================
+  // SIMULATION STATE
+  // ============================================================================
+  let simRunning = false;
+  let simSettled = false;
+  let elapsedTime = 0;
+  let peakImpactForceKN = 0;
+  let currentStepImpulse = 0;
+  let cameraShake = 0;
+
+  let car = null;
+  let bricks = [];
+  let mortarLinks = [];
+  let interLayerLinks = [];
+  let particles = [];
+  let skidMarks = [];
+  let warmCache = new Map();
+
+  // Camera pan/zoom state
+  const camera = {
+    panX: 0,
+    panY: 0,
+    zoom: 1.0,
+    isDragging: false,
+    dragStartX: 0,
+    dragStartY: 0
+  };
+
+  // ============================================================================
+  // SCENE CONSTRUCTION
+  // ============================================================================
+  function buildScene() {
+    simRunning = false;
+    simSettled = false;
+    elapsedTime = 0;
+    peakImpactForceKN = 0;
+    currentStepImpulse = 0;
+    cameraShake = 0;
+    vfxRng = createSeededRandom(1337);
+    warmCache.clear();
+    particles = [];
+    skidMarks = [];
+    bricks = [];
+    mortarLinks = [];
+    interLayerLinks = [];
+
+    // Create Car waiting on the left
+    car = new CarBody(CAR_START_X, 0);
+
+    // Create Freestanding Staggered Brick Wall on the right
+    const cols = config.wallColumns;
+    const rows = config.wallRows;
+    const layers = config.wallDepthLayers;
+    const bw = DEFAULTS.brickWidth;
+    const bh = DEFAULTS.brickHeight;
+    const bMass = config.brickMass;
+
+    let idCounter = 1;
+    // Layer grid lookup: grid[layer][row][col]
+    const grid = [];
+
+    for (let l = 0; l < layers; l++) {
+      grid[l] = [];
+      // Alternate layers have a subtle horizontal bond offset so depth layers overlap seams
+      const layerStagger = (l % 2 === 1) ? bw * 0.25 : 0;
+
+      for (let r = 0; r < rows; r++) {
+        grid[l][r] = [];
+        // Running-bond staggered brick pattern: odd rows shifted by half brick width (0.25 m)
+        const rowStagger = (r % 2 === 1) ? bw * 0.5 : 0;
+        const y = bh * 0.5 + r * bh;
+
+        for (let c = 0; c < cols; c++) {
+          const x = WALL_START_X + bw * 0.5 + c * bw + rowStagger + layerStagger;
+          // Deterministic terracotta brick shade index
+          const shade = ((c * 7 + r * 13 + l * 5) % 5) / 4;
+          const brick = new RigidBrick(idCounter++, c, r, l, x, y, bw, bh, bMass, shade);
+          bricks.push(brick);
+          grid[l][r][c] = brick;
+        }
+      }
+    }
+
+    // Create brittle mortar joints between neighboring bricks in the same layer
+    // and shear/header joints across overlapping depth layers
+    for (let l = 0; l < layers; l++) {
+      for (let r = 0; r < rows; r++) {
+        for (let c = 0; c < cols; c++) {
+          const bA = grid[l][r][c];
+          // Horizontal neighbor in same row
+          if (c + 1 < cols) {
+            const bB = grid[l][r][c + 1];
+            mortarLinks.push({
+              a: bA,
+              b: bB,
+              restDx: bB.x - bA.x,
+              restDy: bB.y - bA.y,
+              maxImpulse: bMass * 1.45,
+              broken: false
+            });
+          }
+          // Vertical neighbors in row above
+          if (r + 1 < rows) {
+            for (let c2 = Math.max(0, c - 1); c2 <= Math.min(cols - 1, c + 1); c2++) {
+              const bUp = grid[l][r + 1][c2];
+              if (Math.abs(bUp.x - bA.x) < bw * 0.78) {
+                mortarLinks.push({
+                  a: bA,
+                  b: bUp,
+                  restDx: bUp.x - bA.x,
+                  restDy: bUp.y - bA.y,
+                  maxImpulse: bMass * 1.65,
+                  broken: false
+                });
+              }
+            }
+          }
+          // Inter-layer header bond to overlapping brick in next depth layer
+          if (l + 1 < layers) {
+            const bNextLayer = grid[l + 1][r][c];
+            interLayerLinks.push({
+              a: bA,
+              b: bNextLayer,
+              restDx: bNextLayer.x - bA.x,
+              restDy: bNextLayer.y - bA.y,
+              maxImpulse: bMass * 2.1,
+              broken: false
+            });
+            if (c + 1 < cols) {
+              const bNextDiag = grid[l + 1][r][c + 1];
+              if (Math.abs(bNextDiag.x - bA.x) < bw * 0.78) {
+                interLayerLinks.push({
+                  a: bA,
+                  b: bNextDiag,
+                  restDx: bNextDiag.x - bA.x,
+                  restDy: bNextDiag.y - bA.y,
+                  maxImpulse: bMass * 1.8,
+                  broken: false
+                });
+              }
+            }
+          }
+        }
+      }
+    }
+
+    updateTelemetryUI();
+  }
+
+  function startTest() {
+    buildScene();
+    car.vx = config.carSpeed;
+    simRunning = true;
+    simSettled = false;
+    updateTelemetryUI();
+  }
+
+  // ============================================================================
+  // PHYSICS SOLVER STEP
+  // ============================================================================
+  function stepPhysics(dt) {
+    const g = DEFAULTS.gravity;
+    currentStepImpulse = 0;
+
+    // 1. Integrate forces (gravity + car suspension + ground friction after impact)
+    for (let i = 0; i < bricks.length; i++) {
+      const b = bricks[i];
+      b.vy -= g * dt;
+      // Slight air/rotational damping for numerical stability
+      b.vx *= 0.9997;
+      b.vy *= 0.9997;
+      b.omega *= 0.9985;
+    }
+
+    // Car dynamics
+    if (car.hasImpacted) {
+      // Ground tire braking + rolling friction once impact begins
+      const decel = DEFAULTS.groundFriction * g;
+      if (Math.abs(car.vx) > 0.001) {
+        const sign = Math.sign(car.vx);
+        const dv = decel * dt;
+        if (Math.abs(car.vx) <= dv) {
+          car.vx = 0;
+        } else {
+          car.vx -= sign * dv;
+        }
+        // Record tire skid marks when braking hard under impact
+        if (Math.abs(car.vx) > 0.4 && Math.floor(elapsedTime * 240) % 3 === 0) {
+          const rearWheelX = car.x - car.w * 0.30;
+          const frontWheelX = car.x + car.w * 0.30 - car.crumple * 0.6;
+          skidMarks.push({ x: rearWheelX, alpha: Math.min(0.65, Math.abs(car.vx) / 25) });
+          skidMarks.push({ x: frontWheelX, alpha: Math.min(0.75, Math.abs(car.vx) / 22) });
+        }
+      }
+    }
+
+    // Car suspension spring-damper keeping it on the track while allowing realistic pitch & heave on impact
+    const yErr = car.y - car.baseY;
+    const springFy = -yErr * 85000 - car.vy * 9500;
+    car.vy += (springFy * car.invMass - g * 0.15) * dt;
+
+    const angErr = car.angle;
+    const springTorque = -angErr * 165000 - car.omega * 18000;
+    car.omega += springTorque * car.invInertia * dt;
+
+    // Clamp extreme car pitch/heave
+    if (car.y < car.baseY - 0.14) {
+      car.y = car.baseY - 0.14;
+      if (car.vy < 0) car.vy *= -0.2;
+    }
+
+    // 2. Solve brittle mortar & inter-layer links (transfers force waves before snapping)
+    solveStructuralLinks(mortarLinks, dt, 0.32);
+    solveStructuralLinks(interLayerLinks, dt, 0.40);
+
+    // 3. Collect all collision manifolds:
+    //    - Brick vs Ground
+    //    - Car vs Bricks (across all depth layers)
+    //    - Brick vs Brick (within same depth layer)
+    const constraints = [];
+    const nextWarmCache = new Map();
+
+    // 3a. Brick vs Ground (y = 0)
+    for (let i = 0; i < bricks.length; i++) {
+      const b = bricks[i];
+      if (b.y - b.radius > 0.02) continue;
