+    // Main Car Body Silhouette (Sport Sedan / Crash Test Vehicle)
+    const bodyGrad = ctx.createLinearGradient(0, roofY, 0, bottomY);
+    bodyGrad.addColorStop(0, "#f97316");
+    bodyGrad.addColorStop(0.45, "#ea580c");
+    bodyGrad.addColorStop(1, "#9a3412");
+
+    ctx.fillStyle = bodyGrad;
+    ctx.strokeStyle = "#fed7aa";
+    ctx.lineWidth = 1.4;
+
+    ctx.beginPath();
+    // Rear bumper bottom
+    ctx.moveTo(rearX + 6, bottomY);
+    // Front bumper bottom
+    ctx.lineTo(frontX - 8, bottomY);
+    // Crumpled front bumper / grille nose
+    ctx.lineTo(frontX, bottomY - 0.22 * ppm);
+    ctx.lineTo(frontX - 4 - crumplePx * 0.15, beltY + 4);
+    // Hood line to base of windshield
+    ctx.lineTo(hw * 0.28, beltY);
+    // Windshield A-pillar up to roof
+    ctx.lineTo(hw * 0.02, roofY);
+    // Roofline to C-pillar
+    ctx.lineTo(-hw * 0.56, roofY + 2);
+    // Rear window down to trunk deck
+    ctx.lineTo(-hw * 0.80, beltY + 2);
+    // Trunk deck
+    ctx.lineTo(rearX + 4, beltY + 6);
+    // Rear tail
+    ctx.lineTo(rearX, bottomY - 0.24 * ppm);
+    ctx.closePath();
+    ctx.fill();
+    ctx.stroke();
+
+    // Crash Test Diagonal High-Visibility Telemetry Stripes & Target Door Decal
+    ctx.save();
+    ctx.clip();
+    ctx.fillStyle = "#0f172a";
+    ctx.fillRect(-hw * 0.18, beltY + 3, hw * 0.42, (bottomY - beltY) * 0.55);
+    ctx.fillStyle = "#facc15";
+    ctx.font = `700 ${Math.max(9, Math.round(0.14 * ppm))}px SFMono-Regular, Consolas, monospace`;
+    ctx.textAlign = "center";
+    ctx.fillText("TEST-01", hw * 0.03, beltY + 0.26 * ppm);
+
+    // Checkerboard crash test strip along lower rocker panel
+    const sq = Math.max(4, 0.11 * ppm);
+    for (let x = rearX + 20; x < frontX - 20; x += sq) {
+      const idx = Math.floor((x - rearX) / sq);
+      ctx.fillStyle = idx % 2 === 0 ? "#facc15" : "#0f172a";
+      ctx.fillRect(x, bottomY - sq * 1.4, sq, sq * 0.7);
+    }
+    ctx.restore();
+
+    // Cabin Windows (Front & Rear side glass + crash test dummy silhouette)
+    ctx.fillStyle = "#0f172a";
+    ctx.strokeStyle = "rgba(226, 232, 240, 0.4)";
+    ctx.lineWidth = 1.2;
+
+    // Front window
+    ctx.beginPath();
+    ctx.moveTo(hw * 0.22, beltY - 1);
+    ctx.lineTo(-hw * 0.01, roofY + 6);
+    ctx.lineTo(-hw * 0.22, roofY + 6);
+    ctx.lineTo(-hw * 0.22, beltY - 1);
+    ctx.closePath();
+    ctx.fill();
+    ctx.stroke();
+
+    // Crash test dummy head & torso visible inside front cabin
+    const dummyLean = Math.min(0.45, carObj.crumple * 1.6);
+    ctx.fillStyle = "#facc15";
+    ctx.beginPath();
+    ctx.arc(-hw * 0.06 + dummyLean * 18, beltY - 0.23 * ppm, 0.11 * ppm, 0, Math.PI * 2);
+    ctx.fill();
+    ctx.fillStyle = "#cbd5e1";
+    ctx.fillRect(-hw * 0.11 + dummyLean * 10, beltY - 0.12 * ppm, 0.10 * ppm, 0.12 * ppm);
+
+    // Rear window
+    ctx.fillStyle = "#0f172a";
+    ctx.beginPath();
+    ctx.moveTo(-hw * 0.27, beltY - 1);
+    ctx.lineTo(-hw * 0.27, roofY + 6);
+    ctx.lineTo(-hw * 0.53, roofY + 8);
+    ctx.lineTo(-hw * 0.73, beltY - 1);
+    ctx.closePath();
+    ctx.fill();
+    ctx.stroke();
+
+    // Headlight & Taillight
+    ctx.fillStyle = "#fef08a";
+    ctx.fillRect(frontX - 7, beltY + 6, 6, 9);
+    // Headlight beam cone
+    if (carObj.crumple < 0.22) {
+      const beamGrad = ctx.createLinearGradient(frontX, 0, frontX + 1.8 * ppm, 0);
+      beamGrad.addColorStop(0, "rgba(254, 240, 138, 0.26)");
+      beamGrad.addColorStop(1, "rgba(254, 240, 138, 0)");
+      ctx.fillStyle = beamGrad;
+      ctx.beginPath();
+      ctx.moveTo(frontX, beltY + 6);
+      ctx.lineTo(frontX + 1.8 * ppm, beltY - 18);
+      ctx.lineTo(frontX + 1.8 * ppm, bottomY + 12);
+      ctx.lineTo(frontX, bottomY - 4);
+      ctx.closePath();
+      ctx.fill();
+    }
+
+    // Taillight (bright red when braking on impact)
+    ctx.fillStyle = carObj.hasImpacted ? "#ff1e1e" : "#991b1b";
+    ctx.fillRect(rearX + 1, beltY + 8, 6, 11);
+
+    // Fiducial markers on car body
+    drawFiducialMarker(-hw * 0.45, beltY + 0.18 * ppm, Math.max(4, 0.08 * ppm));
+    drawFiducialMarker(hw * 0.24 - crumplePx * 0.4, beltY + 0.18 * ppm, Math.max(4, 0.08 * ppm));
+
+    // Wheels (Front & Rear)
+    const wheelRadius = 0.34 * ppm;
+    const wheelY = hh + (carObj.clearance - 0.34) * ppm;
+    const rearWheelX = -hw * 0.62;
+    const frontWheelX = hw * 0.62 - crumplePx * 0.65;
+
+    drawWheel(rearWheelX, wheelY, wheelRadius, carObj.wheelAngle);
+    drawWheel(frontWheelX, wheelY, wheelRadius, carObj.wheelAngle);
+
+    ctx.restore();
+  }
+
+  function drawWheel(wx, wy, r, angle) {
+    ctx.save();
+    ctx.translate(wx, wy);
+
+    // Wheel arch cutout shadow
+    ctx.beginPath();
+    ctx.arc(0, 0, r * 1.14, Math.PI, 0);
+    ctx.fillStyle = "#090d16";
+    ctx.fill();
+
+    ctx.rotate(-angle);
+
+    // Tire
+    ctx.beginPath();
+    ctx.arc(0, 0, r, 0, Math.PI * 2);
+    ctx.fillStyle = "#18181b";
+    ctx.fill();
+    ctx.lineWidth = 2;
+    ctx.strokeStyle = "#3f3f46";
+    ctx.stroke();
+
+    // Alloy rim
+    ctx.beginPath();
+    ctx.arc(0, 0, r * 0.62, 0, Math.PI * 2);
+    ctx.fillStyle = "#94a3b8";
+    ctx.fill();
+
+    // 5 Spokes so wheel rotation is clearly visible
+    ctx.strokeStyle = "#1e293b";
+    ctx.lineWidth = Math.max(2, r * 0.14);
+    for (let i = 0; i < 5; i++) {
+      const a = (i * Math.PI * 2) / 5;
+      ctx.beginPath();
+      ctx.moveTo(0, 0);
+      ctx.lineTo(Math.cos(a) * r * 0.58, Math.sin(a) * r * 0.58);
+      ctx.stroke();
+    }
+
+    // Center hub
+    ctx.beginPath();
+    ctx.arc(0, 0, r * 0.18, 0, Math.PI * 2);
+    ctx.fillStyle = "#f97316";
+    ctx.fill();
+
+    ctx.restore();
+  }
+
+  function drawParticles(vp) {
+    for (let i = 0; i < particles.length; i++) {
+      const p = particles[i];
+      const sx = vp.toScreenX(p.x);
+      const sy = vp.toScreenY(p.y);
+      const alpha = Math.max(0, Math.min(1, p.life));
+
+      if (p.isChip) {
+        ctx.save();
+        ctx.translate(sx, sy);
+        ctx.rotate(p.rot);
+        ctx.fillStyle = `rgba(194, 82, 52, ${alpha})`;
+        ctx.fillRect(-p.size * 0.5, -p.size * 0.35, p.size, p.size * 0.7);
+        ctx.restore();
+      } else {
+        ctx.beginPath();
+        ctx.arc(sx, sy, p.size, 0, Math.PI * 2);
+        ctx.fillStyle = `rgba(203, 195, 183, ${alpha * 0.24})`;
+        ctx.fill();
+      }
+    }
+  }
+
+  // ============================================================================
+  // TELEMETRY & UI SYNCHRONIZATION
+  // ============================================================================
+  function countMovingBricks() {
+    let moving = 0;
+    for (let i = 0; i < bricks.length; i++) {
+      const b = bricks[i];
+      const speedSq = b.vx * b.vx + b.vy * b.vy;
+      if (speedSq > 0.015 || Math.abs(b.omega) > 0.12) {
+        moving++;
+      }
+    }
+    return moving;
+  }
+
+  function updateTelemetryUI() {
+    const currentCarSpeed = simRunning ? Math.abs(car.vx) : config.carSpeed;
+    const movingBricks = simRunning ? countMovingBricks() : 0;
+    const totalBricks = bricks.length;
+    const totalWallMass = totalBricks * config.brickMass;
+
+    if (!simRunning) {
+      telState.textContent = "READY";
+      telState.style.color = "#22c55e";
+    } else if (simSettled) {
+      telState.textContent = "SETTLED";
+      telState.style.color = "#38bdf8";
+    } else {
+      telState.textContent = car.hasImpacted ? "IMPACT" : "LAUNCHING";
+      telState.style.color = "#f97316";
+    }
+
+    telSpeed.textContent = `${currentCarSpeed.toFixed(1)} m/s`;
+    telTime.textContent = `${elapsedTime.toFixed(2)} s`;
+    telMoving.textContent = `${movingBricks} / ${totalBricks}`;
+    telWallMass.textContent = `${totalWallMass.toFixed(1)} kg`;
+    telPeakForce.textContent = `${Math.round(peakImpactForceKN)} kN`;
+  }
+
+  function syncSettingsLabels() {
+    const kmh = Math.round(config.carSpeed * 3.6);
+    valSpeed.textContent = `${config.carSpeed} m/s (${kmh} km/h)`;
+    valCols.textContent = `${config.wallColumns} bricks (${(config.wallColumns * DEFAULTS.brickWidth).toFixed(1)} m)`;
+    valRows.textContent = `${config.wallRows} bricks (${(config.wallRows * DEFAULTS.brickHeight).toFixed(2)} m)`;
+    valLayers.textContent = `${config.wallDepthLayers} ${config.wallDepthLayers === 1 ? "layer" : "layers"}`;
+    valBrickMass.textContent = `${config.brickMass.toFixed(1)} kg`;
+  }
+
+  function onSettingsChange() {
+    config.carSpeed = parseFloat(inpSpeed.value);
+    config.wallColumns = parseInt(inpCols.value, 10);
+    config.wallRows = parseInt(inpRows.value, 10);
+    config.wallDepthLayers = parseInt(inpLayers.value, 10);
+    config.brickMass = parseFloat(inpBrickMass.value);
+
+    syncSettingsLabels();
+    buildScene();
+  }
+
+  inpSpeed.addEventListener("input", onSettingsChange);
+  inpCols.addEventListener("input", onSettingsChange);
+  inpRows.addEventListener("input", onSettingsChange);
+  inpLayers.addEventListener("input", onSettingsChange);
+  inpBrickMass.addEventListener("input", onSettingsChange);
+
+  btnTest.addEventListener("click", startTest);
+  btnReset.addEventListener("click", buildScene);
+
+  btnToggleSettings.addEventListener("click", () => {
+    settingsPanel.classList.toggle("collapsed");
+  });
+
+  btnDefaults.addEventListener("click", () => {
+    inpSpeed.value = DEFAULTS.carSpeed;
+    inpCols.value = DEFAULTS.wallColumns;
+    inpRows.value = DEFAULTS.wallRows;
+    inpLayers.value = DEFAULTS.wallDepthLayers;
+    inpBrickMass.value = DEFAULTS.brickMass;
+    onSettingsChange();
+  });
+
+  // Keyboard shortcuts
+  window.addEventListener("keydown", (e) => {
+    if (e.target.tagName === "INPUT") return;
+    if (e.code === "Space" || e.code === "Enter") {
+      e.preventDefault();
+      startTest();
+    } else if (e.code === "KeyR") {
+      e.preventDefault();
+      buildScene();
+    }
+  });
+
+  // Canvas Pan & Zoom Controls
+  canvas.addEventListener("mousedown", (e) => {
+    camera.isDragging = true;
+    camera.dragStartX = e.clientX - camera.panX;
+    camera.dragStartY = e.clientY - camera.panY;
+  });
+
+  window.addEventListener("mousemove", (e) => {
+    if (!camera.isDragging) return;
+    camera.panX = e.clientX - camera.dragStartX;
+    camera.panY = e.clientY - camera.dragStartY;
+  });
+
+  window.addEventListener("mouseup", () => {
+    camera.isDragging = false;
+  });
+
+  canvas.addEventListener("wheel", (e) => {
+    e.preventDefault();
+    const factor = e.deltaY < 0 ? 1.08 : 0.92;
+    camera.zoom = Math.max(0.45, Math.min(2.5, camera.zoom * factor));
+  }, { passive: false });
+
+  canvas.addEventListener("dblclick", () => {
+    camera.panX = 0;
+    camera.panY = 0;
+    camera.zoom = 1.0;
+  });
+
+  // ============================================================================
+  // MAIN SIMULATION LOOP (DETERMINISTIC FIXED-STEP ACCUMULATOR)
+  // ============================================================================
+  let lastFrameTime = performance.now();
+  let settledFrames = 0;
+
+  function loop(now) {
+    const frameDelta = Math.min(0.05, (now - lastFrameTime) / 1000);
+    lastFrameTime = now;
+
+    if (simRunning && !simSettled) {
+      // Exactly 4 deterministic sub-steps of 1/240s per visual frame (1/60s)
+      for (let s = 0; s < 4; s++) {
+        stepPhysics(FIXED_DT);
+      }
+      updateParticles(FIXED_DT * 4);
+
+      const movingCount = countMovingBricks();
+      if (car.hasImpacted && Math.abs(car.vx) < 0.02 && movingCount === 0 && elapsedTime > 0.8) {
+        settledFrames++;
+        if (settledFrames > 25) {
+          simSettled = true;
+        }
+      } else {
+        settledFrames = 0;
+      }
+
+      updateTelemetryUI();
+    } else if (particles.length > 0 || cameraShake > 0) {
+      updateParticles(frameDelta);
+    }
+
+    render();
+    requestAnimationFrame(loop);
+  }
+
+  // Initialize baseline experiment scene on load
+  syncSettingsLabels();
+  buildScene();
+  requestAnimationFrame(loop);
+})();
+</script>
+</body>
+</html>

