node -e '
const fs = require("fs");
const html = fs.readFileSync("index.html", "utf8");
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];

const elements = {};
const makeEl = (id) => ({
  id,
  value: id === "inpSpeed" ? "22" : id === "inpCols" ? "12" : id === "inpRows" ? "8" : id === "inpLayers" ? "2" : id === "inpBrickMass" ? "2.5" : "",
  textContent: "",
  style: {},
  classList: { toggle: () => {} },
  addEventListener: (ev, fn) => { elements[id + "_" + ev] = fn; },
  getContext: () => new Proxy({}, { get: () => () => ({ addColorStop: () => {} }) })
});

global.window = {
  innerWidth: 1440,
  innerHeight: 900,
  devicePixelRatio: 1,
  addEventListener: () => {}
};
global.document = {
  getElementById: (id) => (elements[id] = elements[id] || makeEl(id))
};
global.performance = { now: () => 0 };
let rafCb = null;
global.requestAnimationFrame = (cb) => { rafCb = cb; };

eval(script);
console.log("Initial state:", elements.telState.textContent, "Speed:", elements.telSpeed.textContent, "Moving:", elements.telMoving.textContent, "WallMass:", elements.telWallMass.textContent);

// Trigger Test
elements.btnTest_click();
for (let f = 1; f <= 180; f++) {
  rafCb(f * 16.666);
  if (f % 30 === 0) {
    console.log(`Frame ${f} (${elements.telTime.textContent}): State=${elements.telState.textContent}, Speed=${elements.telSpeed.textContent}, Moving=${elements.telMoving.textContent}, Peak=${elements.telPeakForce.textContent}`);
  }
}
'

